                    </li>
                  );
                })}
              </ul>
            )}
          </section>
        </>
      ) : (
        <>
          <p>Match {tournament.currentMatch + 1} of {tournament.matches.length}</p>
          <div className="control-row tournament-actions">
            {tournament.phase === 'ready' && (
              <button type="button" className="control" onClick={() => {
                setTournament({ ...tournament, phase: 'playing' });
                setNotice('');
              }}>Start turn</button>
            )}
            {(tournament.phase === 'turnComplete' || tournament.phase === 'matchComplete') && (
              <button type="button" className="control" onClick={() => setTournament(advanceTournament(tournament))}>
                {tournament.phase === 'turnComplete' ? 'Next turn' : 'Next match'}
              </button>
            )}
            {tournament.phase === 'complete' ? (
              <>
                <button type="button" className="control" onClick={back}>Back to game</button>
                <button type="button" className="control" onClick={() => setTournament(null)}>New tournament</button>
              </>
            ) : <button type="button" className="control" onClick={back}>Leave tournament</button>}
          </div>
          {tournament.phase === 'ready' && <p className="help">Pass the device to {player === null ? '' : tournament.players[player]}, then select Start turn.</p>}
          {tournament.phase === 'playing' && match && (
            <TournamentTurn
              key={`${tournament.id}/${tournament.currentMatch}/${tournament.turn}`}
              ref={turnGame}
              code={match.boardCode}
              snapshot={tournament.snapshot}
              complete={complete}
            />
          )}
          {tournament.phase === 'turnComplete' && <p>Game finished. Select Next turn to pass the device.</p>}
          {tournament.phase === 'matchComplete' && match?.winner !== null && (
            <p>Match winner: {tournament.players[match?.winner ?? -1]}</p>
          )}
          <TournamentBracket tournament={tournament} />
        </>
      )}
      <TournamentTransfer exportTournament={exportTournament} loadTournament={loadTournament} />
      <p role="status" aria-live="polite" aria-atomic="true">{notice}</p>
      {saveNotice && <p role="alert">{saveNotice}</p>}
    </div>
  );
}

